 a=a.copy()
 for i in range(14):
  t=a.reshape(-1,2,1<<i);u=t[:,0,:].copy();t[:,0,:]+=t[:,1,:];t[:,1,:]=u-t[:,1,:]
 return a
def pflat(m):
 p=[0]
 for i in range(14):
  if m>>i&1:p +=[x^(1<<i) for x in p]
 return p
def bitpts(b):
 p=[]
 while b:t=b&-b;p.append(t.bit_length()-1);b^=t
 return p
