  for ga,gb in itertools.permutations(gm,2):
   if (ga&gb).bit_count()!=(fa&fb).bit_count():continue
   gc={s:[i for i in range(14) if ((ga>>i&1)+2*(gb>>i&1))==s] for s in range(4)};mp={j:i for s in range(4) for j,i in zip(gc[s],fc[s])};GG=0
